import matplotlib.pyplot as plt
import numpy as np
from matplotlib.colors import ListedColormap

# --- 1. 从 Log 提取的真实数据 (保持不变) ---
target_str = ""
baseline_str = ""
target_bits = np.array([int(b) for b in target_str])
baseline_bits = np.array([int(b) for b in baseline_str])
defense_bits = np.ones(1024)  # vID/vGLO 防御后全是 1

# --- 3. 绘图 ---
fig, axes = plt.subplots(3, 1, figsize=(18, 7), dpi=300)
plt.subplots_adjust(hspace=0.8)

# --- 修正后的颜色：稍微加深一点，增强对比度 ---
# A 图: 白色背景, 亮天空蓝 (对比度更强)
light_blue_cmap = ListedColormap(["#FFFFFF", "#348ABD"])

# B & C 图: 白色背景, 柔和粉红 (确保 B 图条纹和 C 图长条视觉效果厚实)
light_red_cmap = ListedColormap(["#FFFFFF", "#EF4A4A"])


# --- 绘图函数中建议微调 alpha ---
def plot_bits_custom(ax, data, title, cmap, accuracy):
    # alpha=1.0 确保颜色完全显示，不透明
    ax.imshow(
        data.reshape(1, -1),
        aspect="auto",
        cmap=cmap,
        interpolation="nearest",
        vmin=0,
        vmax=1,
        alpha=1.0,
    )

    # ... 其余代码保持不变 ...
    ax.set_title(
        f"{title} (Accuracy: {accuracy}%)",
        loc="left",
        fontsize=16,
        fontweight="bold",
        pad=10,
    )
    ax.set_yticks([])
    ax.set_xticks(np.arange(0, 1025, 128))
    ax.set_xlabel(
        f"Bit Index (0-1023) | Deep Color = Bit '1', White = Bit '0'",
        fontsize=15,
        color="black",
    )


# A. Target (淡淡蓝)
plot_bits_custom(
    axes[0],
    target_bits,
    "A. Target RSA Key (Original)",
    light_blue_cmap,
    100.0,
)

# B. Baseline (淡淡红条纹)
plot_bits_custom(
    axes[1],
    baseline_bits,
    "B. Baseline Recovery (XPT Leakage Identified)",
    light_red_cmap,
    97.95,
)

# C. XPTGuard (全淡淡红长条)
plot_bits_custom(
    axes[2],
    defense_bits,
    "C. XPTGuard Defense (Constant Signal - Obfuscated)",
    light_red_cmap,
    49.61,
)

plt.tight_layout()
plt.savefig("rsa_thesis_light_minimalist.png", bbox_inches="tight")
plt.show()

print("✅ 论文专用极淡色调图已生成！A为淡淡蓝，B、C为淡淡红。")
